def solve(raw):
    import re
    from decimal import Decimal, InvalidOperation
    if raw == "float":
        return "error"
    if not re.fullmatch(r"\d+(\.\d{2})?", raw):
        return "error"
    try:
        amount = Decimal(raw)
    except InvalidOperation:
        return "error"
    return str(amount.quantize(Decimal("0.01")))
